const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Get Puerto Rico geometry from FAO GAUL dataset
  const countries = ee.FeatureCollection('FAO/GAUL/2015/level0');
  const puertoRico = countries.filter(ee.Filter.eq('ADM0_NAME', 'Puerto Rico'));
  const geometry = puertoRico.geometry();

  // Define dates (single days)
  const date1 = '2016-09-21';
  const date2 = '2016-09-22';

  // 2. Data Acquisition - NASA/VNP46A1 (VIIRS Black Marble daily)
  const collectionId = 'NASA/VNP46A1';
  const band = 'DNB_At_Sensor_Radiance_500m';
  const qaBand = 'QF_DNB';

  // Function to get and process image for a specific date
  function getImage(date) {
    const start = ee.Date(date);
    const end = start.advance(1, 'day');
    const col = ee.ImageCollection(collectionId)
      .filterDate(start, end)
      .filterBounds(geometry);
    return col;
  }

  // Get collections for both dates
  const col1 = getImage(date1);
  const col2 = getImage(date2);

  // Check if collections are empty
  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  if (size1 === 0 || size2 === 0) {
    console.log(`2016-09-21 Images: ${size1}, 2016-09-22 Images: ${size2}`);
    console.log('<answer>C1</answer>');
    return;
  }

  // Get first image from each collection
  const img1 = col1.first();
  const img2 = col2.first();

  // 3. Processing - Mask poor quality pixels (QF_DNB == 0 for high quality)
  const masked1 = img1.updateMask(img1.select(qaBand).eq(0));
  const masked2 = img2.updateMask(img2.select(qaBand).eq(0));

  // Function to compute mean and count
  function computeStats(image) {
    const reduced = image.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: geometry,
      scale: 1000,
      maxPixels: 1e9
    });
    return reduced;
  }

  const stats1 = computeStats(masked1.select(band));
  const stats2 = computeStats(masked2.select(band));

  const mean1 = stats1.get('mean');
  const count1 = stats1.get('count');
  const mean2 = stats2.get('mean');
  const count2 = stats2.get('count');

  // Get values (synchronously)
  const mean1Val = mean1.getInfo();
  const count1Val = count1.getInfo();
  const mean2Val = mean2.getInfo();
  const count2Val = count2.getInfo();

  // Check for no valid pixels
  if (count1Val === 0 || count2Val === 0) {
    console.log(`2016-09-21 Valid Pixels: ${count1Val}, 2016-09-22 Valid Pixels: ${count2Val}`);
    console.log('<answer>C2</answer>');
    return;
  }

  // Check for calculation failures
  if (mean1Val === null || mean2Val === null || 
      isNaN(mean1Val) || isNaN(mean2Val)) {
    console.log(`2016-09-21 Mean: ${mean1Val}, 2016-09-22 Mean: ${mean2Val}`);
    console.log('<answer>C3</answer>');
    return;
  }

  // 4. Output stats and determine answer
  console.log(`2016-09-21 Mean Radiance: ${mean1Val.toFixed(4)}, Valid Pixels: ${count1Val}`);
  console.log(`2016-09-22 Mean Radiance: ${mean2Val.toFixed(4)}, Valid Pixels: ${count2Val}`);

  // 5. Final comparison
  if (mean2Val < mean1Val) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
